import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.json.stringify.js";
import "core-js/modules/web.url-search-params.delete.js";
import "core-js/modules/web.url-search-params.has.js";
import "core-js/modules/web.url-search-params.size.js";
import { ElMessage } from 'element-plus';
import fetchWithAuth from '@/utils/fetchWithAuth';
import { validImageDimensions, needsPermanentLinkTab } from '@/utils/fileDetailHelpers';
export default {
  name: 'FileDetailDialog',
  props: {
    modelValue: {
      type: Boolean,
      default: false
    },
    file: {
      type: Object,
      default: null
    },
    fileLink: {
      type: String,
      default: ''
    },
    urls: {
      type: Object,
      default: () => ({
        originUrl: '',
        mdUrl: '',
        htmlUrl: '',
        bbUrl: '',
        tgId: '',
        S3Location: '',
        S3CdnFileUrl: ''
      })
    }
  },
  emits: ['update:modelValue', 'download', 'tagManagement', 'block', 'white', 'delete', 'metadataUpdated', 'fileRenamed'],
  mounted() {
    if (this.visible) this.loadIdentity();
  },
  watch: {
    visible(val) {
      if (val) this.loadIdentity();
      if (!val) {
        // 关闭弹窗时退出编辑状态
        this.isEditing = false;
        this.editSaving = false;
      }
    },
    'file.name'() {
      this.measuredDimensions = null;
      this.dimensionAttemptKey = '';
      if (this.visible) this.loadIdentity();
    },
    showPermanentLink(value) {
      if (!value && this.activeTab === 'permanentLink') this.activeTab = 'originUrl';
    }
  },
  data() {
    return {
      activeTab: 'originUrl',
      fixedId: '',
      identityLoading: false,
      identityError: false,
      measuredDimensions: null,
      dimensionAttemptKey: '',
      isEditing: false,
      editForm: {
        FileName: '',
        FileType: ''
      },
      editSaving: false
    };
  },
  computed: {
    permanentLink() {
      return this.fixedId ? `${window.location.origin}/file/${this.fixedId}` : '';
    },
    showPermanentLink() {
      return needsPermanentLinkTab(this.urls.originUrl, this.permanentLink, window.location.origin);
    },
    visible: {
      get() {
        return this.modelValue;
      },
      set(val) {
        this.$emit('update:modelValue', val);
      }
    },
    dialogWidth() {
      return window.innerWidth < 768 ? '95%' : '900px';
    },
    descColumn() {
      return window.innerWidth < 768 ? 1 : 2;
    },
    isVideo() {
      // 先通过 content-type 判断
      const fileType = this.file?.metadata?.FileType?.toLowerCase() || '';
      if (fileType.includes('video')) return true;
      // 再通过文件后缀判断
      const name = this.file?.name?.toLowerCase() || '';
      return name.endsWith('.mp4') || name.endsWith('.webm') || name.endsWith('.mov') || name.endsWith('.avi');
    },
    isAudio() {
      // 先通过 content-type 判断
      const fileType = this.file?.metadata?.FileType?.toLowerCase() || '';
      if (fileType.includes('audio')) return true;
      // 再通过文件后缀判断
      const name = this.file?.name?.toLowerCase() || '';
      return name.endsWith('.mp3') || name.endsWith('.wav') || name.endsWith('.ogg') || name.endsWith('.flac');
    },
    isImage() {
      // 先通过 content-type 判断
      const fileType = this.file?.metadata?.FileType?.toLowerCase() || '';
      if (fileType.includes('image')) return true;
      // 再通过文件后缀判断
      const name = this.file?.name?.toLowerCase() || '';
      return name.endsWith('.jpg') || name.endsWith('.jpeg') || name.endsWith('.png') || name.endsWith('.gif') || name.endsWith('.webp') || name.endsWith('.svg') || name.endsWith('.bmp') || name.endsWith('.avif') || name.endsWith('.heic') || name.endsWith('.heif');
    },
    uploadTime() {
      if (this.file?.metadata?.TimeStamp) {
        return new Date(this.file.metadata.TimeStamp).toLocaleString();
      }
      return this.$t('fileDetail.unknown');
    },
    accessType() {
      const listType = this.file?.metadata?.ListType;
      const label = this.file?.metadata?.Label;
      if (listType === 'White') return this.$t('fileDetail.accessNormalWhitelist');
      if (listType === 'Block') return this.$t('fileDetail.accessBlockedBlacklist');
      if (label === 'adult') return this.$t('fileDetail.accessBlockedReview');
      return this.$t('fileDetail.accessNormal');
    },
    accessTagType() {
      const listType = this.file?.metadata?.ListType;
      const label = this.file?.metadata?.Label;
      if (listType === 'White') return 'success';
      if (listType === 'Block') return 'danger';
      if (label === 'adult') return 'danger';
      return 'success';
    },
    imageDimensions() {
      return this.measuredDimensions || validImageDimensions(this.file?.metadata?.Width, this.file?.metadata?.Height);
    },
    orientationIcon() {
      const width = this.imageDimensions?.width;
      const height = this.imageDimensions?.height;
      if (!width || !height) return '';
      const ratio = width / height;
      if (ratio > 1.1) return this.$t('fileDetail.orientationLandscape');
      if (ratio < 0.9) return this.$t('fileDetail.orientationPortrait');
      return this.$t('fileDetail.orientationSquare');
    },
    fileSizeDisplay() {
      const sizeBytes = this.file?.metadata?.FileSizeBytes;
      const sizeMB = this.file?.metadata?.FileSize;
      if (sizeBytes) {
        // 根据大小选择合适的单位
        if (sizeBytes < 1024) {
          return `${sizeBytes} B`;
        } else if (sizeBytes < 1024 * 1024) {
          return `${(sizeBytes / 1024).toFixed(2)} KB`;
        } else {
          return `${(sizeBytes / 1024 / 1024).toFixed(2)} MB`;
        }
      } else if (sizeMB) {
        return `${sizeMB} MB`;
      }
      return this.$t('fileDetail.unknown');
    }
  },
  methods: {
    async handleImageLoad(event) {
      const image = event?.target;
      const dimensions = validImageDimensions(image?.naturalWidth, image?.naturalHeight);
      if (!dimensions || !this.file?.name || !this.isImage) return;
      // Ignore late load events belonging to the previously selected image.
      try {
        if (new URL(image.currentSrc || image.src, window.location.origin).href !== new URL(this.fileLink, window.location.origin).href) return;
      } catch {
        return;
      }
      const path = this.file.name;
      this.measuredDimensions = dimensions;
      const saved = validImageDimensions(this.file.metadata?.Width, this.file.metadata?.Height);
      if (saved?.width === dimensions.width && saved?.height === dimensions.height) return;
      const key = `${path}:${dimensions.width}x${dimensions.height}`;
      if (this.dimensionAttemptKey === key) return;
      this.dimensionAttemptKey = key;
      try {
        const encodedPath = path.split('/').map(encodeURIComponent).join('/');
        const response = await fetchWithAuth(`/api/manage/metadata/${encodedPath}`, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            Width: dimensions.width,
            Height: dimensions.height
          })
        });
        if (!response.ok) return;
        const data = await response.json();
        if (this.file?.name === path) this.$emit('metadataUpdated', path, data.metadata);
      } catch {
        // Keep the decoded dimensions visible even if backfilling metadata fails.
      }
    },
    handleVideoClick(e) {
      const video = e.target;
      if (video.paused) video.play();else video.pause();
    },
    async loadIdentity() {
      const path = this.file?.name;
      if (!path) return;
      this.fixedId = this.file?.metadata?.FixedId || '';
      this.identityError = false;
      if (this.fixedId) {
        this.identityLoading = false;
        return;
      }
      this.identityLoading = true;
      try {
        const encodedPath = path.split('/').map(encodeURIComponent).join('/');
        const response = await fetchWithAuth(`/api/manage/identity/${encodedPath}`, {
          method: 'POST'
        });
        if (!response.ok) throw new Error('Identity initialization failed');
        const data = await response.json();
        if (this.file?.name !== path) return;
        this.fixedId = data.fixedId;
        this.$emit('metadataUpdated', path, data.metadata);
      } catch {
        if (this.file?.name === path) this.identityError = true;
      } finally {
        if (this.file?.name === path) this.identityLoading = false;
      }
    },
    handleTabClick() {},
    handleUrlClick(e) {
      const input = e.target;
      if (!input.value) return;
      input.select();
      navigator.clipboard.writeText(input.value).then(() => {
        ElMessage.success(this.$t('fileDetail.linkCopied'));
      });
    },
    openImageLink() {
      if (this.fileLink) {
        window.open(this.fileLink, '_blank');
      }
    },
    startEdit() {
      this.editForm.FileName = this.file?.metadata?.FileName || '';
      this.editForm.FileType = this.file?.metadata?.FileType || '';
      this.isEditing = true;
    },
    cancelEdit() {
      this.isEditing = false;
      this.editForm.FileName = this.file?.metadata?.FileName || '';
      this.editForm.FileType = this.file?.metadata?.FileType || '';
      this.editSaving = false;
    },
    async saveMetadata() {
      this.editSaving = true;
      try {
        const fileId = this.file.name;
        const response = await fetchWithAuth(`/api/manage/metadata/${fileId.split('/').map(encodeURIComponent).join('/')}`, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            FileName: this.editForm.FileName,
            FileType: this.editForm.FileType
          })
        });
        if (response.ok) {
          const data = await response.json();
          ElMessage.success(this.$t('fileDetail.metadataSaved'));
          this.isEditing = false;
          if (data.newFileId && data.newFileId !== fileId) this.$emit('fileRenamed', fileId, data.newFileId, data.metadata);else this.$emit('metadataUpdated', fileId, data.metadata);
        } else {
          const error = await response.json().catch(() => ({}));
          throw new Error(error.message || this.$t('fileDetail.metadataSaveFailed'));
        }
      } catch (error) {
        console.error('Error saving metadata:', error);
        ElMessage.error(error.message || this.$t('fileDetail.metadataSaveFailed'));
      } finally {
        this.editSaving = false;
      }
    }
  }
};